import React, { useState } from 'react';
import { Trash2, Plus, Users, Play, Clock, Layers, Calendar, FileText, Download, ShieldCheck } from 'lucide-react';

// Helper to add hours to a time string (HH:mm)
const addHours = (time, hours) => {
  const [h, m] = time.split(':').map(Number);
  const newH = h + hours;
  return `${String(newH).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
};

const DepartmentCard = ({ dept, onUpdate, onGenerate, globalSchedule = [], allDepartments = [] }) => {
  const [activeTab, setActiveTab] = useState("subjects");
  const [localPreview, setLocalPreview] = useState([]);
  const { subjects, proctors, rooms, name: deptName, code: deptCode, id: deptId } = dept;

  // --- GENERATOR UI STATES ---
  const [examDays, setExamDays] = useState(0); 
  const [examDates, setExamDates] = useState([]);
  const [startTime, setStartTime] = useState("08:00");
  const [selectedYear, setSelectedYear] = useState("1");
  const [sectionCount, setSectionCount] = useState(0); 
  const [proctorSource, setProctorSource] = useState("Department");
  const [roomSource, setRoomSource] = useState("Department");

  // --- INPUT STATES ---
  const [pName, setPName] = useState("");
  const [pDayStart, setPDayStart] = useState("");
  const [pDayEnd, setPDayEnd] = useState("");
  const [pTimeStart, setPTimeStart] = useState("08:00");
  const [pTimeEnd, setPTimeEnd] = useState("17:00");
  const [roomNum, setRoomNum] = useState("");

  const handleExamDayChange = (val) => {
    const num = parseInt(val) || 0;
    setExamDays(num);
    setExamDates(new Array(num).fill(''));
  };

  const exportToExcel = () => {
    if (localPreview.length === 0) return alert("Generate a schedule first!");
    const headers = "Section,Date,Time Range,Room,Proctor,Subjects\n";
    const rows = localPreview.map(row => 
      `${row.section},${row.exam_date},"${row.start_time}-${row.end_time}",${row.room},${row.proctor},"${row.subjects.join(' | ')}"`
    ).join("\n");

    const blob = new Blob([headers + rows], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${deptCode}_Year${selectedYear}_Schedule.csv`;
    link.click();
  };

  const handleGenerateClick = () => {
    const yearSubjects = subjects[selectedYear];
    if (yearSubjects.length === 0) return alert("No subjects found for this year level!");
    if (examDays === 0 || sectionCount === 0) return alert("Set days and sections!");
    if (examDates.some(d => !d)) return alert("Set all exam dates!");

    // 1. SHUFFLE & DISTRIBUTE SUBJECTS ACROSS DAYS
    const shuffled = [...yearSubjects].sort(() => Math.random() - 0.5);
    const dailySplit = Array.from({ length: examDays }, () => []);
    shuffled.forEach((sub, i) => dailySplit[i % examDays].push(sub));

    const finalGeneratedData = [];
    const previewData = [];

    for (let d = 0; d < examDays; d++) {
      const daySubjects = dailySplit[d];
      const currentDate = examDates[d];
      const duration = daySubjects.length; 
      const calculatedEndTime = addHours(startTime, duration);

      const roomPool = roomSource === "Global" ? allDepartments.flatMap(dept => dept.rooms) : rooms;
      const proctorPool = proctorSource === "Global" ? allDepartments.flatMap(dept => dept.proctors) : proctors;

      for (let s = 0; s < sectionCount; s++) {
        const sectionID = `${deptCode}${selectedYear}${String.fromCharCode(65 + s)}`; // e.g., BSIS3A

        // Resource Selection
        const selectedRoom = roomPool[s];
        const selectedProctor = proctorPool.find(p => 
          currentDate >= p.dayStart && currentDate <= p.dayEnd &&
          startTime >= p.timeStart && calculatedEndTime <= p.timeEnd &&
          !globalSchedule.some(gs => gs.proctor === p.name && gs.exam_date === currentDate && (startTime < gs.end_time && calculatedEndTime > gs.start_time))
        );

        if (!selectedRoom) return alert(`Insufficient rooms for ${sectionID}`);
        if (!selectedProctor) return alert(`No available proctor for ${sectionID} on Day ${d+1}`);

        // PREVIEW BUNDLE
        previewData.push({
          section: sectionID,
          exam_date: currentDate,
          start_time: startTime,
          end_time: calculatedEndTime,
          room: selectedRoom.number,
          proctor: selectedProctor.name,
          subjects: daySubjects.map(sub => sub.code)
        });

        // DETAILED LOG FOR MASTER CALENDAR
        daySubjects.forEach((sub, index) => {
          finalGeneratedData.push({
            subject_code: sub.code,
            subject_name: sub.name,
            section: sectionID,
            year_level: selectedYear,
            dept_code: deptCode,
            exam_date: currentDate,
            start_time: addHours(startTime, index),
            end_time: addHours(startTime, index + 1),
            room: selectedRoom.number,
            proctor: selectedProctor.name
          });
        });
      }
    }

    setLocalPreview(previewData);
    onGenerate(finalGeneratedData, examDates);
    setActiveTab("preview");
  };

  return (
    <div className="bg-white rounded-[3rem] shadow-2xl border border-slate-200 overflow-hidden mb-12">
      <div className="bg-slate-900 p-8 text-white flex justify-between items-center border-b-4 border-blue-600">
        <h2 className="text-3xl font-black uppercase tracking-tighter italic">{deptName}</h2>
      </div>

      <div className="flex bg-slate-50 p-2 border-b">
        {['subjects', 'proctors', 'rooms', 'generate', 'preview'].map(t => (
          <button key={t} onClick={() => setActiveTab(t)} className={`flex-1 py-4 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === t ? 'bg-white shadow-lg text-blue-600' : 'text-slate-400'}`}>
            {t}
          </button>
        ))}
      </div>

      <div className="p-10">
        {activeTab === 'generate' && (
          <div className="bg-slate-900 rounded-[3rem] p-12 text-white space-y-10">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
              <div className="space-y-6">
                <h4 className="text-blue-400 font-black text-[10px] uppercase tracking-widest">Time Logic</h4>
                <input type="number" value={examDays || ''} onChange={e => handleExamDayChange(e.target.value)} placeholder="Total Exam Days" className="w-full bg-slate-800 p-4 rounded-2xl text-xl font-black text-blue-400" />
                <div className="space-y-2">{examDates.map((d, i) => (<input key={i} type="date" value={d} onChange={e => { const updated = [...examDates]; updated[i] = e.target.value; setExamDates(updated); }} className="w-full bg-slate-800 p-3 rounded-xl text-xs font-bold" />))}</div>
                <input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full bg-slate-800 p-4 rounded-2xl font-black text-blue-400" />
              </div>

              <div className="space-y-6">
                <h4 className="text-emerald-400 font-black text-[10px] uppercase tracking-widest">Section Rules</h4>
                <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)} className="w-full bg-slate-800 p-4 rounded-2xl font-black text-xs text-blue-400">
                  {[1, 2, 3, 4, 5].map(y => <option key={y} value={y}>Year {y}</option>)}
                </select>
                <input type="number" value={sectionCount || ''} onChange={e => setSectionCount(parseInt(e.target.value) || 0)} placeholder="How many sections?" className="w-full bg-slate-800 p-4 rounded-2xl font-black text-emerald-400" />
                <button onClick={handleGenerateClick} className="w-full bg-blue-600 py-8 rounded-[2rem] font-black uppercase tracking-[0.3em] flex items-center justify-center gap-4 hover:bg-blue-500 transition-all shadow-2xl shadow-blue-900/40">
                  <Play size={24} fill="currentColor" /> Generate Section Blocks
                </button>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'preview' && (
          <div className="space-y-6">
            <div className="flex justify-between items-center">
              <h3 className="text-xl font-black uppercase text-slate-800">Generated Schedule: Year {selectedYear}</h3>
              <button onClick={exportToExcel} className="flex items-center gap-2 bg-emerald-600 text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase shadow-lg shadow-emerald-100 hover:bg-emerald-700 transition-all">
                <Download size={16} /> Export to Excel
              </button>
            </div>
            <div className="border-2 border-slate-100 rounded-[2rem] overflow-hidden shadow-sm">
              <table className="w-full text-left">
                <thead className="bg-slate-50 text-[10px] font-black uppercase text-slate-400 border-b">
                  <tr>
                    <th className="p-6">Section</th>
                    <th className="p-6">Date</th>
                    <th className="p-6">Time Block</th>
                    <th className="p-6">Room</th>
                    <th className="p-6">Proctor</th>
                    <th className="p-6">Subjects</th>
                  </tr>
                </thead>
                <tbody className="text-xs font-bold text-slate-600">
                  {localPreview.map((row, i) => (
                    <tr key={i} className="border-b hover:bg-slate-50 transition-colors">
                      <td className="p-6 text-blue-600 font-black">{row.section}</td>
                      <td className="p-6">{row.exam_date}</td>
                      <td className="p-6 text-emerald-600">{row.start_time} - {row.end_time}</td>
                      <td className="p-6">{row.room}</td>
                      <td className="p-6">{row.proctor}</td>
                      <td className="p-6">
                        <div className="flex flex-wrap gap-1">
                          {row.subjects.map(s => <span key={s} className="bg-slate-100 px-2 py-1 rounded text-[9px]">{s}</span>)}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {activeTab === 'subjects' && (
          <div className="space-y-4">
            <div className="grid grid-cols-4 gap-2 bg-slate-50 p-4 rounded-2xl">
              <select className="p-2 rounded-lg text-xs font-bold" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
                {[1, 2, 3, 4, 5].map(y => <option key={y} value={y}>Year {y}</option>)}
              </select>
              <input id={`sC-${deptId}`} placeholder="CODE" className="p-2 rounded-lg text-xs font-bold border-none" />
              <input id={`sN-${deptId}`} placeholder="NAME" className="p-2 rounded-lg text-xs font-bold border-none" />
              <button onClick={() => {
                const c = document.getElementById(`sC-${deptId}`).value;
                const n = document.getElementById(`sN-${deptId}`).value;
                if (c && n) {
                  onUpdate('subjects', { ...subjects, [selectedYear]: [...subjects[selectedYear], { code: c.toUpperCase(), name: n }] });
                  document.getElementById(`sC-${deptId}`).value = '';
                  document.getElementById(`sN-${deptId}`).value = '';
                }
              }} className="bg-blue-600 text-white rounded-lg"><Plus /></button>
            </div>
            <div className="grid grid-cols-2 gap-2">
              {subjects[selectedYear]?.map((s, i) => (
                <div key={i} className="flex justify-between p-4 bg-white border-2 border-slate-50 rounded-2xl items-center font-black text-xs">
                  {s.code}: <span className="text-slate-400">{s.name}</span>
                  <button onClick={() => onUpdate('subjects', { ...subjects, [selectedYear]: subjects[selectedYear].filter((_, idx) => idx !== i) })}><Trash2 size={16} className="text-slate-300 hover:text-rose-500" /></button>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'proctors' && (
          <div className="space-y-6">
            <div className="grid grid-cols-1 md:grid-cols-5 gap-4 bg-emerald-50 p-6 rounded-[2rem] border border-emerald-100">
              <input value={pName} onChange={e => setPName(e.target.value)} placeholder="NAME" className="p-3 rounded-xl text-xs font-bold border-none" />
              <input type="date" value={pDayStart} onChange={e => setPDayStart(e.target.value)} className="p-2 rounded-lg text-[10px]" />
              <input type="date" value={pDayEnd} onChange={e => setPDayEnd(e.target.value)} className="p-2 rounded-lg text-[10px]" />
              <input type="time" value={pTimeStart} onChange={e => setPTimeStart(e.target.value)} className="p-2 rounded-lg text-[10px]" />
              <button onClick={() => {
                if (pName && pDayStart && pDayEnd) {
                  onUpdate('proctors', [...proctors, { id: Date.now(), name: pName.toUpperCase(), dayStart: pDayStart, dayEnd: pDayEnd, timeStart: pTimeStart, timeEnd: "17:00" }]);
                  setPName("");
                }
              }} className="bg-emerald-600 text-white rounded-xl font-black text-[10px] uppercase">Add Staff</button>
            </div>
            <div className="grid grid-cols-2 gap-4">
              {proctors.map(p => (
                <div key={p.id} className="p-4 border-2 border-slate-50 rounded-[2rem] flex justify-between items-center text-xs font-bold uppercase">
                  {p.name} <Trash2 size={16} className="text-slate-200 cursor-pointer hover:text-rose-500" onClick={() => onUpdate('proctors', proctors.filter(item => item.id !== p.id))} />
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'rooms' && (
          <div className="space-y-4">
            <div className="flex gap-2 bg-amber-50 p-4 rounded-2xl border border-amber-100">
              <input value={roomNum} onChange={e => setRoomNum(e.target.value)} placeholder="ROOM #" className="flex-1 p-3 border-none rounded-xl text-xs font-bold shadow-sm" />
              <button onClick={() => { if (roomNum) { onUpdate('rooms', [...rooms, { id: Date.now(), number: roomNum.toUpperCase(), type: 'Department' }]); setRoomNum(""); } }} className="bg-amber-600 text-white px-6 rounded-xl text-[10px] font-black uppercase">Add Room</button>
            </div>
            <div className="grid grid-cols-4 md:grid-cols-6 gap-4">
              {rooms.map(r => (<div key={r.id} className="p-6 bg-slate-50 rounded-[2rem] text-center font-black text-lg border-2 border-transparent hover:border-amber-400 transition-all">{r.number}</div>))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DepartmentCard;
